import { type ChangeEvent, useEffect, useMemo, useRef, useState } from 'react'
import * as XLSX from 'xlsx'

type Role = 'مشتری' | 'کارشناس' | 'مدیر'
type Page = 'home' | 'requests' | 'new-request' | 'detail' | 'dashboard' | 'templates' | 'users' | 'help'

const steps = ['اطلاعات پایه', 'طراحی فرم', 'گردش فرم', 'بازبینی و ارسال']

type RequestListItem = { id: string; name: string; organization: string; status: string; tone: 'warning' | 'info' | 'neutral' | 'success'; date: string; progress: number }
const statusTone: Record<string, RequestListItem['tone']> = {
  'پیش‌نویس': 'neutral',
  'ارسال‌شده توسط مشتری': 'info',
  'در حال بررسی': 'info',
  'نیازمند تکمیل مشتری': 'warning',
  'تأیید نهایی': 'success',
  'آماده طراحی': 'success',
  'بسته‌شده': 'neutral',
}
const requestRows: RequestListItem[] = [
  { id: 'leave-request', name: 'فرم درخواست مرخصی', organization: 'شرکت سپهر', status: 'نیازمند تکمیل مشتری', tone: 'warning', date: '۱۴۰۵/۰۶/۲۴', progress: 65 },
  { id: 'mission-request', name: 'فرم مأموریت اداری', organization: 'گروه آرمان', status: 'در حال بررسی', tone: 'info', date: '۱۴۰۵/۰۶/۲۲', progress: 100 },
  { id: 'purchase-request', name: 'فرم درخواست خرید', organization: 'شرکت سپهر', status: 'پیش‌نویس', tone: 'neutral', date: '۱۴۰۵/۰۶/۲۰', progress: 35 },
]

function Icon({ name }: { name: string }) {
  const symbols: Record<string, string> = { home: '⌂', file: '▤', plus: '+', grid: '▦', users: '♙', layers: '◇', bell: '◌', arrow: '←', check: '✓', clock: '◷', chat: '◌', menu: '☰', search: '⌕', upload: '⇧', close: '×', help: '?' }
  return <span className="icon" aria-hidden>{symbols[name] ?? '•'}</span>
}

function ContextHelp({ title, text }: { title: string; text: string }) {
  const [open, setOpen] = useState(false)
  return <span className="context-help"><button type="button" aria-label={`راهنمای ${title}`} aria-expanded={open} onClick={() => setOpen(!open)}>?</button>{open && <span className="context-help-popover"><strong>{title}</strong><small>{text}</small></span>}</span>
}

export default function App() {
  const [role, setRole] = useState<Role>('مشتری')
  const [page, setPage] = useState<Page>('home')
  const [activeStep, setActiveStep] = useState(0)
  const [notice, setNotice] = useState('')
  const [menuOpen, setMenuOpen] = useState(false)
  const [requests, setRequests] = useState<RequestListItem[]>(() => loadDraft('pargar-requests', requestRows))
  const [requestPayloads, setRequestPayloads] = useState<Record<string, RequestPayload>>(() => loadDraft('pargar-request-payloads', {}))
  const [selectedRequestId, setSelectedRequestId] = useState<string>('leave-request')
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [users, setUsers] = useState<AdminUser[]>(() => loadDraft('pargar-admin-users', initialAdminUsers))
  const [templates, setTemplates] = useState<FormTemplate[]>(() => loadDraft('pargar-templates', initialTemplates))
  useEffect(() => { localStorage.setItem('pargar-admin-users', JSON.stringify(users)) }, [users])
  useEffect(() => { localStorage.setItem('pargar-templates', JSON.stringify(templates)) }, [templates])
  useEffect(() => { localStorage.setItem('pargar-requests', JSON.stringify(requests)) }, [requests])
  useEffect(() => { localStorage.setItem('pargar-request-payloads', JSON.stringify(requestPayloads)) }, [requestPayloads])

  const nav = useMemo(() => role === 'مشتری'
    ? [{ id: 'home', label: 'خانه', icon: 'home' }, { id: 'requests', label: 'درخواست‌های من', icon: 'file' }, { id: 'new-request', label: 'درخواست جدید', icon: 'plus' }, { id: 'help', label: 'راهنمای استفاده', icon: 'help' }]
    : role === 'کارشناس'
      ? [{ id: 'home', label: 'خانه', icon: 'home' }, { id: 'requests', label: 'درخواست‌های قابل بررسی', icon: 'file' }, { id: 'help', label: 'راهنمای استفاده', icon: 'help' }]
      : [{ id: 'dashboard', label: 'داشبورد', icon: 'grid' }, { id: 'requests', label: 'همه درخواست‌ها', icon: 'file' }, { id: 'users', label: 'کاربران', icon: 'users' }, { id: 'templates', label: 'قالب‌ها', icon: 'layers' }, { id: 'help', label: 'راهنمای استفاده', icon: 'help' }], [role])

  const navigate = (next: Page) => { setPage(next); setMenuOpen(false) }
  const toast = (text: string) => { setNotice(text); window.setTimeout(() => setNotice(''), 2600) }
  const openRequest = (id?: string) => { if (id) setSelectedRequestId(id); navigate('detail') }
  const updateRequestStatus = (id: string, status: string) => {
    setRequests((items) => items.map((item) => item.id === id ? { ...item, status, tone: statusTone[status] ?? 'neutral', date: 'همین حالا' } : item))
  }
  const selectedRequest = requests.find((item) => item.id === selectedRequestId) ?? requests[0] ?? requestRows[0]
  const selectedPayload = requestPayloads[selectedRequest.id] ?? { base: initialBase, sections: initialSections, workflow: initialWorkflow, comments: initialComments, history: initialHistory }
  const updateSelectedPayload = (updater: (payload: RequestPayload) => RequestPayload) => {
    setRequestPayloads((items) => ({ ...items, [selectedRequest.id]: updater(items[selectedRequest.id] ?? selectedPayload) }))
  }

  return <div className="app-shell">
    <aside className={`sidebar ${menuOpen ? 'open' : ''}`}>
      <div className="brand"><span className="brand-mark">ف</span><span>فرم‌یار</span></div>
      <div className="role-switcher">
        <span>نمایش نقش:</span>
        <select value={role} onChange={(e) => { setRole(e.target.value as Role); navigate(e.target.value === 'مدیر' ? 'dashboard' : 'home') }}>
          <option>مشتری</option><option>کارشناس</option><option>مدیر</option>
        </select>
      </div>
      <nav>
        {nav.map((item) => <button key={item.id} className={page === item.id ? 'active' : ''} onClick={() => navigate(item.id as Page)}><Icon name={item.icon} />{item.label}</button>)}
      </nav>
      <button className="sidebar-help" onClick={() => navigate('help')}><span className="help-dot">?</span><div><strong>راهنما نیاز دارید؟</strong><small>راهنمای کامل استفاده از سیستم</small></div></button>
      <div className="profile"><div className="avatar">م</div><div><strong>مریم احمدی</strong><small>{role}</small></div><span className="more">⋮</span></div>
    </aside>
    {menuOpen && <button className="backdrop" aria-label="بستن منو" onClick={() => setMenuOpen(false)} />}
    <main>
      <header className="topbar"><button className="mobile-menu" onClick={() => setMenuOpen(true)}><Icon name="menu" /></button><div className="crumb">{page === 'home' ? 'خانه' : page === 'new-request' ? 'درخواست جدید' : page === 'detail' ? 'جزئیات درخواست' : page === 'dashboard' ? 'داشبورد' : page === 'help' ? 'راهنمای استفاده' : 'مدیریت درخواست‌ها'}</div><div className="top-actions"><div className="notification-wrap"><button className="icon-button" onClick={() => setNotificationsOpen(!notificationsOpen)}><Icon name="bell" /><i /></button>{notificationsOpen && <div className="notification-popover"><strong>اعلان‌ها</strong><button onClick={() => { navigate('detail'); setNotificationsOpen(false) }}>یک پرسش برای «فرم درخواست مرخصی» ثبت شده است.</button><button onClick={() => { navigate('requests'); setNotificationsOpen(false) }}>یک درخواست آماده بررسی دارید.</button></div>}</div><button className="user-pill" onClick={() => toast(`شما در نقش ${role} هستید.`)}><div className="avatar small">م</div>مریم احمدی</button></div></header>
      <div className="content">
        {page === 'home' && (role === 'کارشناس' ? <SpecialistHome onRequests={() => navigate('requests')} onDetail={() => openRequest()} /> : <Home onNew={() => navigate('new-request')} onRequests={() => navigate('requests')} role={role} rows={requests} />)}
        {page === 'requests' && <Requests onNew={() => navigate('new-request')} onDetail={openRequest} role={role} rows={requests} />}
        {page === 'new-request' && <NewRequest activeStep={activeStep} setActiveStep={setActiveStep} onCancel={() => navigate('requests')} onSave={() => toast('پیش‌نویس با موفقیت ذخیره شد.')} onSubmitted={(payload) => { const id = crypto.randomUUID(); setRequests((items) => [{ id, name: payload.base.formName, organization: payload.base.organization, status: 'ارسال‌شده توسط مشتری', tone: 'info', date: 'همین حالا', progress: 100 }, ...items]); setRequestPayloads((items) => ({ ...items, [id]: payload })); setSelectedRequestId(id); toast('درخواست با موفقیت برای بررسی ارسال شد.'); navigate('requests') }} />}
        {page === 'detail' && <RequestDetail onBack={() => navigate('requests')} onNew={() => navigate('new-request')} role={role} request={selectedRequest} payload={selectedPayload} onPayloadChange={updateSelectedPayload} onStatusChange={(status) => { updateRequestStatus(selectedRequest.id, status); toast(`وضعیت درخواست به «${status}» تغییر کرد.`) }} />}
        {page === 'dashboard' && <Dashboard onRequests={() => navigate('requests')} rows={requests} />}
        {page === 'templates' && <TemplateManagement templates={templates} setTemplates={setTemplates} toast={toast} />}
        {page === 'users' && <UserManagement users={users} setUsers={setUsers} toast={toast} />}
        {page === 'help' && <HelpCenter role={role} onNavigate={navigate} />}
      </div>
    </main>
    {notice && <div className="toast"><Icon name="check" />{notice}</div>}
  </div>
}

function Home({ onNew, onRequests, role, rows }: { onNew: () => void; onRequests: () => void; role: Role; rows: RequestListItem[] }) {
  return <>
    <section className="welcome"><div><span className="eyebrow">سامانه طراحی فرم و گردش کار</span><h1>سلام مریم، خوش آمدید</h1><p>{role === 'کارشناس' ? 'درخواست‌های منتظر بررسی را ببینید و پیگیری کنید.' : 'نیازمندی فرم خود را مرحله‌به‌مرحله و با راهنمایی ثبت کنید.'}</p><button className="primary" onClick={onNew}><Icon name="plus" />ثبت درخواست جدید</button></div><div className="welcome-illustration"><div className="paper one" /><div className="paper two" /><div className="check-circle">✓</div></div></section>
    <section className="stats-grid"><Stat icon="file" value="۳" label="درخواست فعال" color="blue" /><Stat icon="chat" value="۱" label="نیازمند پاسخ شما" color="orange" /><Stat icon="check" value="۸" label="تکمیل‌شده" color="green" /></section>
    <section className="card"><div className="section-title"><div><h2>درخواست‌های اخیر</h2><p>آخرین فعالیت‌های شما در یک نگاه</p></div><button className="text-button" onClick={onRequests}>مشاهده همه <Icon name="arrow" /></button></div><RequestTable compact onDetail={() => onRequests()} rows={rows.slice(0, 3)} /></section>
  </>
}

function SpecialistHome({ onRequests, onDetail }: { onRequests: () => void; onDetail: () => void }) {
  return <>
    <section className="specialist-welcome"><div><span className="eyebrow">میزکار کارشناس</span><h1>سلام علی، سه درخواست منتظر بررسی است</h1><p>درخواست‌ها را بررسی کنید، ابهام‌ها را به بخش دقیق متصل کنید و نتیجه را برای مشتری ثبت کنید.</p><button className="primary" onClick={onRequests}><Icon name="file" />مشاهده صف بررسی</button></div><div className="review-gauge"><strong>۳</strong><span>در انتظار بررسی</span></div></section>
    <section className="stats-grid"><Stat icon="file" value="۳" label="منتظر شروع بررسی" color="blue" /><Stat icon="chat" value="۲" label="در انتظار پاسخ مشتری" color="orange" /><Stat icon="check" value="۱۲" label="آماده طراحی" color="green" /></section>
    <section className="card"><div className="section-title"><div><h2>اولویت‌های امروز</h2><p>درخواست‌هایی که نیازمند اقدام شما هستند.</p></div><button className="text-button" onClick={onRequests}>مشاهده همه <Icon name="arrow" /></button></div><div className="specialist-queue"><div><span className="priority-dot critical" /><p><strong>فرم درخواست مرخصی</strong><small>شرکت سپهر · ۱ پرسش باز · امروز</small></p><span className="badge warning">نیازمند تکمیل مشتری</span><button className="row-action" onClick={onDetail}>بررسی درخواست <Icon name="arrow" /></button></div><div><span className="priority-dot normal" /><p><strong>فرم مأموریت اداری</strong><small>گروه آرمان · آماده شروع بررسی · دیروز</small></p><span className="badge info">ارسال‌شده توسط مشتری</span><button className="row-action" onClick={onDetail}>شروع بررسی <Icon name="arrow" /></button></div></div></section>
  </>
}

function Stat({ icon, value, label, color }: { icon: string; value: string; label: string; color: string }) { return <div className="stat-card"><div className={`stat-icon ${color}`}><Icon name={icon} /></div><div><strong>{value}</strong><span>{label}</span></div></div> }

function RequestTable({ compact, onDetail, rows = requestRows }: { compact?: boolean; onDetail: (id: string) => void; rows?: RequestListItem[] }) { return <div className="table-wrap"><table><thead><tr><th>نام درخواست</th><th>سازمان</th><th>وضعیت</th><th>آخرین تغییر</th>{!compact && <th>میزان تکمیل</th>}<th /></tr></thead><tbody>{rows.map((row) => <tr key={row.id}><td><strong>{row.name}</strong></td><td>{row.organization}</td><td><span className={`badge ${row.tone}`}>{row.status}</span></td><td>{row.date}</td>{!compact && <td><div className="progress-cell"><span>{row.progress}٪</span><div className="mini-progress"><i style={{ width: `${row.progress}%` }} /></div></div></td>}<td><button className="row-action" onClick={() => onDetail(row.id)}>{row.status === 'پیش‌نویس' ? 'ادامه' : 'مشاهده'} <Icon name="arrow" /></button></td></tr>)}</tbody></table></div> }

function Requests({ onNew, onDetail, role, rows }: { onNew: () => void; onDetail: (id: string) => void; role: Role; rows: RequestListItem[] }) {
  const [query, setQuery] = useState('')
  const [status, setStatus] = useState('')
  const [organization, setOrganization] = useState('')
  const filtered = rows.filter((row) => (!query || `${row.name} ${row.organization}`.includes(query)) && (!status || row.status === status) && (!organization || row.organization === organization))
  return <><div className="page-heading"><div><h1>{role === 'کارشناس' ? 'درخواست‌های قابل بررسی' : role === 'مدیر' ? 'همه درخواست‌ها' : 'درخواست‌های من'}</h1><p>وضعیت و جزئیات نیازمندی‌های ثبت‌شده را دنبال کنید.</p></div>{role === 'مشتری' && <button className="primary" onClick={onNew}><Icon name="plus" />درخواست جدید</button>}</div><section className="card filter-card"><div className="search"><Icon name="search" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="جست‌وجو در درخواست‌ها..." /></div><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">همه وضعیت‌ها</option>{[...new Set(rows.map((row) => row.status))].map((item) => <option key={item}>{item}</option>)}</select><select value={organization} onChange={(event) => setOrganization(event.target.value)}><option value="">همه سازمان‌ها</option>{[...new Set(rows.map((row) => row.organization))].map((item) => <option key={item}>{item}</option>)}</select></section><section className="card">{filtered.length ? <RequestTable onDetail={onDetail} rows={filtered} /> : <div className="empty-results">درخواستی با این فیلتر پیدا نشد. <button onClick={() => { setQuery(''); setStatus(''); setOrganization('') }}>پاک‌کردن فیلترها</button></div>}</section></>
}

function NewRequest({ activeStep, setActiveStep, onCancel, onSave, onSubmitted }: { activeStep: number; setActiveStep: (n: number) => void; onCancel: () => void; onSave: () => void; onSubmitted: (payload: RequestPayload) => void }) {
  const [base, setBase] = useState<BaseDraft>(() => loadDraft('pargar-base-draft', initialBase))
  const [sections, setSections] = useState<FormSectionDraft[]>(() => {
    const stored = localStorage.getItem('pargar-form-draft')
    if (!stored) return initialSections
    try { return JSON.parse(stored) as FormSectionDraft[] } catch { return initialSections }
  })
  const [comments, setComments] = useState<CommentDraft[]>(() => loadDraft('pargar-comments-draft', initialComments))
  const [history, setHistory] = useState<HistoryDraft[]>(() => loadDraft('pargar-history-draft', initialHistory))
  const [submitted, setSubmitted] = useState(false)
  useEffect(() => { localStorage.setItem('pargar-base-draft', JSON.stringify(base)) }, [base])
  useEffect(() => { localStorage.setItem('pargar-form-draft', JSON.stringify(sections)) }, [sections])
  useEffect(() => { localStorage.setItem('pargar-comments-draft', JSON.stringify(comments)) }, [comments])
  useEffect(() => { localStorage.setItem('pargar-history-draft', JSON.stringify(history)) }, [history])
  const [workflow, setWorkflow] = useState<WorkflowDraft>(() => {
    const stored = localStorage.getItem('pargar-workflow-draft')
    if (!stored) return initialWorkflow
    try { return JSON.parse(stored) as WorkflowDraft } catch { return initialWorkflow }
  })
  useEffect(() => { localStorage.setItem('pargar-workflow-draft', JSON.stringify(workflow)) }, [workflow])
  return <>
    <div className="page-heading wizard-heading"><div><button className="back-link" onClick={onCancel}><Icon name="arrow" />بازگشت به درخواست‌ها</button><h1>درخواست جدید طراحی فرم</h1><p>اطلاعات را با دقت وارد کنید؛ هر زمان بخواهید می‌توانید پیش‌نویس را ذخیره کنید.</p></div><button className="secondary" onClick={onSave}>ذخیره پیش‌نویس</button></div>
    <div className="stepper">{steps.map((step, index) => <button key={step} onClick={() => setActiveStep(index)} className={index === activeStep ? 'current' : index < activeStep ? 'complete' : ''}><span>{index < activeStep ? '✓' : index + 1}</span>{step}{index < steps.length - 1 && <i />}</button>)}</div>
    <div className={`wizard-layout ${activeStep > 0 ? 'designer-layout' : ''}`}><section className="card form-card"><div className="form-intro"><span className="form-icon">▤</span><div><h2>{steps[activeStep]} <ContextHelp title={steps[activeStep]} text={activeStep === 0 ? 'نام و هدف فرم اجباری هستند. اطلاعات را با زبان ساده بنویسید و برای نمونه‌های قبلی فایل پیوست کنید.' : activeStep === 1 ? 'هر فیلد باید عنوان، شناسه فنی یکتا، نوع و اجباری‌بودن داشته باشد. فیلدهای کشویی و رادیویی بدون گزینه فعال قابل ارسال نیستند.' : activeStep === 2 ? 'هر اقدام باید یک مرحله مبدأ و فقط یک مقصد داشته باشد: مرحله بعد یا وضعیت پایانی. دست‌کم یک مسیر پایان بسازید.' : 'خطاها را رفع کنید، پیش‌نمایش را کنترل کنید و سپس درخواست را برای بررسی ارسال کنید.'} /></h2><p>{activeStep === 0 ? 'اطلاعات کلی فرم را وارد کنید تا شناخت اولیه‌ای از نیاز شما داشته باشیم.' : activeStep === 1 ? 'بخش‌ها و فیلدهای فرم را اضافه کنید. برای دیدن جزئیات هر فیلد، آن را انتخاب کنید.' : activeStep === 2 ? 'هر اقدام را جداگانه تعریف کنید و برای آن یک مرحله مقصد یا وضعیت پایانی مشخص کنید.' : 'پیش‌نمایش، خطاهای احتمالی، پرسش‌ها و خروجی‌های نهایی را در یک جا ببینید.'}</p></div></div>{activeStep === 0 ? <BasicForm base={base} setBase={setBase} /> : activeStep === 1 ? <FormDesigner sections={sections} setSections={setSections} /> : activeStep === 2 ? <WorkflowDesigner workflow={workflow} setWorkflow={setWorkflow} /> : <ReviewAndSubmit base={base} sections={sections} workflow={workflow} comments={comments} setComments={setComments} history={history} setHistory={setHistory} submitted={submitted} onSubmit={() => { const nextHistory = [{ id: crypto.randomUUID(), title: 'ارسال برای بررسی', detail: 'درخواست برای بررسی کارشناس ارسال شد.', time: 'همین حالا' }, ...history]; setSubmitted(true); setHistory(nextHistory); onSubmitted({ base, sections, workflow, comments, history: nextHistory }) }} />}</section>{activeStep === 0 && <aside className="hint-card"><div className="hint-head"><span>✦</span><strong>راهنمای این بخش</strong></div><p>تا حد امکان از واژه‌هایی استفاده کنید که همکاران سازمان شما نیز با آن‌ها آشنا هستند.</p><div className="hint-example"><small>مثال</small><p>«فرم درخواست مرخصی» برای ثبت و بررسی انواع مرخصی کارکنان استفاده می‌شود.</p></div></aside>}</div>
    <div className="wizard-footer"><button className="secondary" onClick={() => activeStep ? setActiveStep(activeStep - 1) : onCancel()}>{activeStep ? 'مرحله قبل' : 'انصراف'}</button><button className="primary" onClick={() => activeStep < 3 ? setActiveStep(activeStep + 1) : onSave()}>{activeStep === 3 ? 'بازبینی و ارسال' : 'ادامه'}<Icon name="arrow" /></button></div>
  </>
}

function BasicForm({ base, setBase }: { base: BaseDraft; setBase: (value: BaseDraft) => void }) {
  const fileInput = useRef<HTMLInputElement>(null)
  const input = (key: keyof BaseDraft, value: string) => setBase({ ...base, [key]: value })
  const selectFiles = (event: ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = Array.from(event.target.files ?? []).map((file) => ({ id: crypto.randomUUID(), name: file.name, size: file.size, type: file.type || 'نامشخص' }))
    setBase({ ...base, attachments: [...base.attachments, ...selectedFiles] })
    event.target.value = ''
  }
  return <div className="field-grid">
    <label>نام فرم<em>*</em><input value={base.formName} onChange={(event) => input('formName', event.target.value)} placeholder="مثال: فرم درخواست مرخصی" /></label>
    <label>سازمان / مشتری<em>*</em><input value={base.organization} onChange={(event) => input('organization', event.target.value)} placeholder="نام سازمان را انتخاب یا وارد کنید" /></label>
    <label>واحد مالک فرایند<em>*</em><input value={base.ownerUnit} onChange={(event) => input('ownerUnit', event.target.value)} placeholder="مثال: منابع انسانی" /></label>
    <label>هدف فرم<em>*</em><textarea value={base.purpose} onChange={(event) => input('purpose', event.target.value)} placeholder="این فرم چه مسئله‌ای را حل می‌کند؟" rows={3} /><small>مثال: ثبت درخواست مرخصی، بررسی مدیر و اطلاع‌رسانی نتیجه به کارمند.</small></label>
    <label className="full">مخاطبان / استفاده‌کنندگان فرم<input value={base.audiences} onChange={(event) => input('audiences', event.target.value)} placeholder="مثال: همه کارکنان و مدیران مستقیم" /></label>
    <label className="full">شرح مختصر فرایند<textarea value={base.briefProcess} onChange={(event) => input('briefProcess', event.target.value)} placeholder="مراحل کلی کار را به زبان ساده توضیح دهید" rows={4} /></label>
    <label><span>اولویت</span><div className="priority-options">{(['عادی', 'فوری', 'خیلی فوری'] as const).map((priority) => <button type="button" key={priority} className={base.priority === priority ? 'selected' : ''} onClick={() => input('priority', priority)}>{priority}</button>)}</div></label>
    <label className="full"><span>فایل‌های پیوست یا فرم‌های قدیمی</span><input ref={fileInput} className="hidden-file-input" type="file" multiple accept=".pdf,.xlsx,.xls,.doc,.docx,image/*" onChange={selectFiles} /><button type="button" className="upload-zone" onClick={() => fileInput.current?.click()}><Icon name="upload" /><strong>برای انتخاب فایل کلیک کنید</strong><small>PDF، Excel، Word یا تصویر — حداکثر ۱۰ مگابایت برای هر فایل</small></button>{base.attachments.length > 0 && <div className="attachment-list">{base.attachments.map((file) => <div key={file.id}><span>▤</span><p><strong>{file.name}</strong><small>{Math.ceil(file.size / 1024)} کیلوبایت · {file.type}</small></p><button type="button" className="delete" aria-label={`حذف ${file.name}`} onClick={() => setBase({ ...base, attachments: base.attachments.filter((item) => item.id !== file.id) })}>×</button></div>)}</div>}</label>
  </div>
}

type FieldKind = 'SHORT_TEXT' | 'LONG_TEXT' | 'NUMBER' | 'CURRENCY' | 'DATE' | 'TIME' | 'BOOLEAN' | 'SELECT' | 'RADIO' | 'SYSTEM_LOOKUP' | 'ATTACHMENT' | 'SIGNATURE' | 'REPEATING_TABLE' | 'STATIC_TEXT' | 'STATIC_IMAGE'
type OptionDraft = { id: string; code: string; title: string; active: boolean }
type FormFieldDraft = { id: string; technicalId: string; title: string; type: FieldKind; required: boolean; readOnly: boolean; help: string; defaultValue: string; exampleValue: string; visibilityRule: string; validationRule: string; dataSource: string; calculationLogic: string; options: OptionDraft[] }
type FormSectionDraft = { id: string; title: string; fields: FormFieldDraft[] }

const fieldTypeLabels: Record<FieldKind, string> = { SHORT_TEXT: 'متن کوتاه', LONG_TEXT: 'متن چندخطی', NUMBER: 'عدد', CURRENCY: 'مبلغ', DATE: 'تاریخ', TIME: 'ساعت', BOOLEAN: 'بله/خیر', SELECT: 'کشویی', RADIO: 'رادیویی', SYSTEM_LOOKUP: 'انتخاب از اطلاعات سیستم', ATTACHMENT: 'پیوست', SIGNATURE: 'امضا', REPEATING_TABLE: 'جدول چندسطری', STATIC_TEXT: 'متن ثابت', STATIC_IMAGE: 'تصویر ثابت' }
const createField = (index: number): FormFieldDraft => ({ id: crypto.randomUUID(), technicalId: `field_${index}`, title: 'فیلد جدید', type: 'SHORT_TEXT', required: false, readOnly: false, help: '', defaultValue: '', exampleValue: '', visibilityRule: '', validationRule: '', dataSource: '', calculationLogic: '', options: [] })
const initialSections: FormSectionDraft[] = [{ id: 'general', title: 'اطلاعات درخواست', fields: [{ ...createField(1), id: 'requester', technicalId: 'requester_name', title: 'نام درخواست‌دهنده', type: 'SYSTEM_LOOKUP', readOnly: true, defaultValue: 'کاربر جاری', dataSource: 'فهرست کاربران سیستم' }, { ...createField(2), id: 'leave-type', technicalId: 'leave_type', title: 'نوع مرخصی', type: 'SELECT', required: true, help: 'نوع مرخصی مورد نظر را انتخاب کنید.', options: [{ id: 'annual', code: 'ANNUAL', title: 'استحقاقی', active: true }, { id: 'sick', code: 'SICK', title: 'استعلاجی', active: true }] }, { ...createField(3), id: 'start-date', technicalId: 'start_date', title: 'تاریخ شروع', type: 'DATE', required: true, exampleValue: '۱۴۰۵/۰۷/۰۱' }] }]

function FormDesigner({ sections, setSections }: { sections: FormSectionDraft[]; setSections: (sections: FormSectionDraft[]) => void }) {
  const [selected, setSelected] = useState<{ sectionId: string; fieldId: string } | null>({ sectionId: 'general', fieldId: 'leave-type' })
  const current = selected ? sections.find((section) => section.id === selected.sectionId)?.fields.find((field) => field.id === selected.fieldId) : null
  const duplicateIds = sections.flatMap((section) => section.fields.map((field) => field.technicalId)).filter((value, index, list) => value && list.indexOf(value) !== index)
  const updateField = (key: keyof FormFieldDraft, value: string | boolean | OptionDraft[]) => { if (!selected) return; setSections(sections.map((section) => section.id !== selected.sectionId ? section : { ...section, fields: section.fields.map((field) => field.id === selected.fieldId ? { ...field, [key]: value } : field) })) }
  const addField = (sectionId: string) => { const section = sections.find((item) => item.id === sectionId)!; const field = createField(section.fields.length + 1); setSections(sections.map((item) => item.id === sectionId ? { ...item, fields: [...item.fields, field] } : item)); setSelected({ sectionId, fieldId: field.id }) }
  const removeField = (sectionId: string, fieldId: string) => { setSections(sections.map((section) => section.id === sectionId ? { ...section, fields: section.fields.filter((field) => field.id !== fieldId) } : section)); if (selected?.fieldId === fieldId) setSelected(null) }
  const moveField = (sectionId: string, index: number, direction: -1 | 1) => { const next = [...sections]; const sectionIndex = next.findIndex((section) => section.id === sectionId); const fields = [...next[sectionIndex].fields]; const target = index + direction; if (target < 0 || target >= fields.length) return; [fields[index], fields[target]] = [fields[target], fields[index]]; next[sectionIndex] = { ...next[sectionIndex], fields }; setSections(next) }
  const addSection = () => { const section = { id: crypto.randomUUID(), title: `بخش ${sections.length + 1}`, fields: [] }; setSections([...sections, section]) }
  const isOptionBased = current?.type === 'SELECT' || current?.type === 'RADIO'
  const updateOption = (id: string, key: keyof OptionDraft, value: string | boolean) => updateField('options', (current?.options ?? []).map((option) => option.id === id ? { ...option, [key]: value } : option))
  return <div className="designer">
    <div className="designer-toolbar"><div><strong>ساختار فرم</strong><small>{sections.length} بخش و {sections.reduce((count, section) => count + section.fields.length, 0)} فیلد تعریف شده</small></div><button className="secondary compact" onClick={addSection}><Icon name="plus" />افزودن بخش</button></div>
    {duplicateIds.length > 0 && <div className="designer-warning">شناسه فنی «{duplicateIds[0]}» تکراری است؛ برای هر فیلد یک شناسه یکتا وارد کنید.</div>}
    <div className="designer-content"><div className="section-list">{sections.map((section) => <div className="designer-section" key={section.id}><div className="section-header"><input value={section.title} aria-label="نام بخش" onChange={(event) => setSections(sections.map((item) => item.id === section.id ? { ...item, title: event.target.value } : item))} /><span>{section.fields.length} فیلد</span></div><div className="field-items">{section.fields.map((field, index) => <div className={`field-item ${selected?.fieldId === field.id ? 'selected' : ''}`} key={field.id} onClick={() => setSelected({ sectionId: section.id, fieldId: field.id })}><span className="drag-handle">⠿</span><div><strong>{field.title || 'بدون عنوان'}</strong><small>{fieldTypeLabels[field.type]} · {field.required ? 'اجباری' : 'اختیاری'}</small></div><div className="field-actions"><button aria-label="انتقال به بالا" disabled={!index} onClick={(event) => { event.stopPropagation(); moveField(section.id, index, -1) }}>↑</button><button aria-label="انتقال به پایین" disabled={index === section.fields.length - 1} onClick={(event) => { event.stopPropagation(); moveField(section.id, index, 1) }}>↓</button><button aria-label="حذف فیلد" className="delete" onClick={(event) => { event.stopPropagation(); removeField(section.id, field.id) }}>×</button></div></div>)}</div><button className="add-field" onClick={() => addField(section.id)}><Icon name="plus" />افزودن فیلد</button></div>)}</div>
      <aside className="field-editor">{current ? <><div className="editor-heading"><div><span>تنظیمات فیلد</span><h3>{current.title || 'فیلد جدید'}</h3></div><span className="field-type-chip">{fieldTypeLabels[current.type]}</span></div><div className="editor-grid"><label>عنوان نمایشی<em>*</em><input value={current.title} onChange={(event) => updateField('title', event.target.value)} placeholder="مثال: تاریخ شروع" /></label><label>شناسه فنی<em>*</em><input dir="ltr" value={current.technicalId} onChange={(event) => updateField('technicalId', event.target.value.replace(/\s/g, '_'))} placeholder="start_date" /></label><label>نوع فیلد<em>*</em><select value={current.type} onChange={(event) => updateField('type', event.target.value)}>{Object.entries(fieldTypeLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label>راهنمای تکمیل<textarea value={current.help} onChange={(event) => updateField('help', event.target.value)} placeholder="راهنمایی کوتاه برای کاربر" rows={2} /></label><label className="full">مقدار پیش‌فرض<input value={current.defaultValue} onChange={(event) => updateField('defaultValue', event.target.value)} placeholder="مثال: تاریخ امروز یا کاربر جاری" /></label><label>مثال مقدار<input value={current.exampleValue} onChange={(event) => updateField('exampleValue', event.target.value)} placeholder="مثال قابل‌فهم" /></label><label>منبع داده<input value={current.dataSource} onChange={(event) => updateField('dataSource', event.target.value)} placeholder="مثال: فهرست واحدها" /></label><label className="full">شرط نمایش<input value={current.visibilityRule} onChange={(event) => updateField('visibilityRule', event.target.value)} placeholder="مثال: فقط زمانی که نوع درخواست = مأموریت است" /></label><label>محدودیت و اعتبارسنجی<input value={current.validationRule} onChange={(event) => updateField('validationRule', event.target.value)} placeholder="مثال: حداکثر ۱۰ رقم" /></label><label>فرمول یا منطق محاسبه<input value={current.calculationLogic} onChange={(event) => updateField('calculationLogic', event.target.value)} placeholder="مثال: تعداد × مبلغ واحد" /></label></div><div className="switch-row"><label><input type="checkbox" checked={current.required} onChange={(event) => updateField('required', event.target.checked)} />اجباری است</label><label><input type="checkbox" checked={current.readOnly} onChange={(event) => updateField('readOnly', event.target.checked)} />فقط‌خواندنی است</label></div>{isOptionBased && <div className="option-manager"><div className="option-heading"><div><h4>گزینه‌ها</h4><small>کد، عنوان و ترتیب هر گزینه را مشخص کنید.</small></div><button className="secondary compact" onClick={() => updateField('options', [...current.options, { id: crypto.randomUUID(), code: `OPTION_${current.options.length + 1}`, title: 'گزینه جدید', active: true }])}><Icon name="plus" />گزینه</button></div>{current.options.length === 0 && <div className="empty-options">هنوز گزینه‌ای اضافه نشده است.</div>}{current.options.map((option, index) => <div className="option-row" key={option.id}><span>{index + 1}</span><input dir="ltr" value={option.code} onChange={(event) => updateOption(option.id, 'code', event.target.value)} aria-label="کد گزینه" /><input value={option.title} onChange={(event) => updateOption(option.id, 'title', event.target.value)} aria-label="عنوان گزینه" /><label title="فعال"><input type="checkbox" checked={option.active} onChange={(event) => updateOption(option.id, 'active', event.target.checked)} /></label><button className="delete" aria-label="حذف گزینه" onClick={() => updateField('options', current.options.filter((item) => item.id !== option.id))}>×</button></div>)}</div>}</> : <div className="empty-editor"><div>▤</div><strong>یک فیلد را انتخاب کنید</strong><p>برای ویرایش مشخصات، نوع و تنظیمات فیلد روی آن کلیک کنید.</p></div>}</aside></div>
  </div>
}

type TerminalStatus = 'COMPLETED' | 'REJECTED' | 'CANCELLED' | 'NEEDS_CORRECTION'
type WorkflowStageDraft = { id: string; name: string; responsible: string; dueDays: string; description: string }
type WorkflowActionDraft = { id: string; sourceStageId: string; title: string; condition: string; targetStageId: string; terminalStatus: TerminalStatus | ''; recipients: string; description: string }
type WorkflowDraft = { stages: WorkflowStageDraft[]; actions: WorkflowActionDraft[] }

const terminalLabels: Record<TerminalStatus, string> = { COMPLETED: 'تکمیل‌شده', REJECTED: 'ردشده', CANCELLED: 'ابطال‌شده', NEEDS_CORRECTION: 'نیازمند اصلاح' }
const initialWorkflow: WorkflowDraft = {
  stages: [
    { id: 'register', name: 'ثبت درخواست', responsible: 'همه کارکنان', dueDays: '', description: 'درخواست توسط کارمند ثبت می‌شود.' },
    { id: 'manager', name: 'بررسی مدیر', responsible: 'مدیر مستقیم', dueDays: '2', description: 'مدیر مستقیم درخواست را بررسی می‌کند.' },
    { id: 'hr', name: 'بررسی منابع انسانی', responsible: 'کارشناس منابع انسانی', dueDays: '2', description: 'تطبیق با ضوابط و نهایی‌سازی نتیجه.' },
  ],
  actions: [
    { id: 'send', sourceStageId: 'register', title: 'ارسال', condition: '', targetStageId: 'manager', terminalStatus: '', recipients: 'مدیر مستقیم', description: '' },
    { id: 'manager-approve', sourceStageId: 'manager', title: 'تأیید', condition: '', targetStageId: 'hr', terminalStatus: '', recipients: 'کارشناس منابع انسانی', description: '' },
    { id: 'manager-reject', sourceStageId: 'manager', title: 'رد درخواست', condition: '', targetStageId: '', terminalStatus: 'REJECTED', recipients: 'درخواست‌دهنده', description: '' },
    { id: 'manager-return', sourceStageId: 'manager', title: 'برگشت جهت اصلاح', condition: '', targetStageId: 'register', terminalStatus: '', recipients: 'درخواست‌دهنده', description: '' },
    { id: 'hr-approve', sourceStageId: 'hr', title: 'تأیید نهایی', condition: '', targetStageId: '', terminalStatus: 'COMPLETED', recipients: 'درخواست‌دهنده', description: '' },
  ],
}

function WorkflowDesigner({ workflow, setWorkflow }: { workflow: WorkflowDraft; setWorkflow: (workflow: WorkflowDraft) => void }) {
  const [selectedActionId, setSelectedActionId] = useState<string>('manager-approve')
  const selectedAction = workflow.actions.find((action) => action.id === selectedActionId) ?? null
  const updateAction = (key: keyof WorkflowActionDraft, value: string) => { if (!selectedAction) return; setWorkflow({ ...workflow, actions: workflow.actions.map((action) => action.id === selectedAction.id ? { ...action, [key]: value } : action) }) }
  const addStage = () => { const stage: WorkflowStageDraft = { id: crypto.randomUUID(), name: `مرحله ${workflow.stages.length + 1}`, responsible: '', dueDays: '', description: '' }; setWorkflow({ ...workflow, stages: [...workflow.stages, stage] }) }
  const updateStage = (id: string, key: keyof WorkflowStageDraft, value: string) => setWorkflow({ ...workflow, stages: workflow.stages.map((stage) => stage.id === id ? { ...stage, [key]: value } : stage) })
  const removeStage = (id: string) => { if (workflow.stages.length === 1) return; setWorkflow({ stages: workflow.stages.filter((stage) => stage.id !== id), actions: workflow.actions.filter((action) => action.sourceStageId !== id && action.targetStageId !== id) }); if (selectedAction?.sourceStageId === id || selectedAction?.targetStageId === id) setSelectedActionId('') }
  const moveStage = (index: number, direction: -1 | 1) => { const stages = [...workflow.stages]; const target = index + direction; if (target < 0 || target >= stages.length) return; [stages[index], stages[target]] = [stages[target], stages[index]]; setWorkflow({ ...workflow, stages }) }
  const addAction = () => { const source = workflow.stages[0]?.id ?? ''; const action: WorkflowActionDraft = { id: crypto.randomUUID(), sourceStageId: source, title: 'اقدام جدید', condition: '', targetStageId: '', terminalStatus: '', recipients: '', description: '' }; setWorkflow({ ...workflow, actions: [...workflow.actions, action] }); setSelectedActionId(action.id) }
  const removeAction = (id: string) => { setWorkflow({ ...workflow, actions: workflow.actions.filter((action) => action.id !== id) }); if (selectedActionId === id) setSelectedActionId('') }
  const targetLabel = (action: WorkflowActionDraft) => action.terminalStatus ? terminalLabels[action.terminalStatus] : workflow.stages.find((stage) => stage.id === action.targetStageId)?.name || 'مقصد مشخص نشده'
  return <div className="workflow-designer">
    <div className="workflow-toolbar"><div><strong>ساختار گردش فرم</strong><small>{workflow.stages.length} مرحله و {workflow.actions.length} اقدام مستقل</small></div><button className="secondary compact" onClick={addStage}><Icon name="plus" />افزودن مرحله</button></div>
    <div className="workflow-canvas"><div className="workflow-canvas-title"><span>نمای ساده گردش فرم</span><small>هر فلش یک اقدام مستقل است.</small></div><div className="flow-nodes">{workflow.stages.map((stage, index) => <div className="flow-item" key={stage.id}><div className="flow-node"><span>{index + 1}</span><strong>{stage.name || 'بدون نام'}</strong><small>{stage.responsible || 'مسئول مشخص نشده'}</small></div>{index < workflow.stages.length - 1 && <i className="flow-line">←</i>}</div>)}<div className="terminal-mini"><span>پایان</span><small>تکمیل / رد / ابطال</small></div></div><div className="flow-actions">{workflow.actions.map((action) => <button key={action.id} className={selectedActionId === action.id ? 'selected' : ''} onClick={() => setSelectedActionId(action.id)}><strong>{workflow.stages.find((stage) => stage.id === action.sourceStageId)?.name || '—'}</strong><span>{action.title || 'اقدام بدون عنوان'} ← {targetLabel(action)}</span></button>)}</div></div>
    <div className="workflow-grid"><section className="stage-manager"><div className="subheading"><div><h3>مراحل</h3><p>برای هر مرحله یک مسئول مشخص کنید.</p></div></div>{workflow.stages.map((stage, index) => <div className="stage-card" key={stage.id}><div className="stage-order"><button disabled={!index} onClick={() => moveStage(index, -1)}>↑</button><b>{index + 1}</b><button disabled={index === workflow.stages.length - 1} onClick={() => moveStage(index, 1)}>↓</button></div><div className="stage-fields"><input value={stage.name} onChange={(event) => updateStage(stage.id, 'name', event.target.value)} placeholder="نام مرحله" /><input value={stage.responsible} onChange={(event) => updateStage(stage.id, 'responsible', event.target.value)} placeholder="نقش یا واحد مسئول" /><div><input type="number" min="0" value={stage.dueDays} onChange={(event) => updateStage(stage.id, 'dueDays', event.target.value)} placeholder="مهلت (روز)" /><input value={stage.description} onChange={(event) => updateStage(stage.id, 'description', event.target.value)} placeholder="توضیحات (اختیاری)" /></div></div><button className="delete stage-delete" aria-label="حذف مرحله" onClick={() => removeStage(stage.id)}>×</button></div>)}</section>
      <section className="action-manager"><div className="subheading"><div><h3>اقدام‌ها</h3><p>هر اقدام به‌صورت مستقل ثبت می‌شود.</p></div><button className="secondary compact" onClick={addAction}><Icon name="plus" />اقدام</button></div><div className="action-list">{workflow.actions.map((action) => <button key={action.id} className={`action-card ${selectedActionId === action.id ? 'selected' : ''}`} onClick={() => setSelectedActionId(action.id)}><span className="action-source">{workflow.stages.find((stage) => stage.id === action.sourceStageId)?.name || 'بدون مبدأ'}</span><strong>{action.title || 'اقدام بدون عنوان'}</strong><small>مقصد: {targetLabel(action)}</small></button>)}</div>{selectedAction ? <div className="action-editor"><div className="action-editor-title"><strong>ویرایش اقدام</strong><button className="delete" onClick={() => removeAction(selectedAction.id)}>حذف اقدام</button></div><div className="action-editor-grid"><label>مرحله مبدأ<em>*</em><select value={selectedAction.sourceStageId} onChange={(event) => updateAction('sourceStageId', event.target.value)}>{workflow.stages.map((stage) => <option key={stage.id} value={stage.id}>{stage.name}</option>)}</select></label><label>عنوان اقدام<em>*</em><input value={selectedAction.title} onChange={(event) => updateAction('title', event.target.value)} placeholder="مثال: تأیید" /></label><label className="full">شرط انجام اقدام<input value={selectedAction.condition} onChange={(event) => updateAction('condition', event.target.value)} placeholder="اختیاری؛ مثال: مدت مرخصی بیش از ۳ روز باشد" /></label><label>مرحله مقصد<select value={selectedAction.targetStageId} onChange={(event) => { updateAction('targetStageId', event.target.value); if (event.target.value) updateAction('terminalStatus', '') }}><option value="">انتخاب نشده</option>{workflow.stages.filter((stage) => stage.id !== selectedAction.sourceStageId).map((stage) => <option key={stage.id} value={stage.id}>{stage.name}</option>)}</select></label><label>وضعیت پایانی<select value={selectedAction.terminalStatus} onChange={(event) => { updateAction('terminalStatus', event.target.value); if (event.target.value) updateAction('targetStageId', '') }}><option value="">ندارد</option>{Object.entries(terminalLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label className="full">اعلان‌گیرندگان<input value={selectedAction.recipients} onChange={(event) => updateAction('recipients', event.target.value)} placeholder="مثال: درخواست‌دهنده، مدیر مستقیم" /></label><label className="full">توضیحات<textarea value={selectedAction.description} onChange={(event) => updateAction('description', event.target.value)} rows={2} placeholder="توضیحات تکمیلی اقدام" /></label></div><small className="destination-note">برای هر اقدام، فقط یکی از «مرحله مقصد» یا «وضعیت پایانی» را مشخص کنید.</small></div> : <div className="empty-actions">یک اقدام را انتخاب کنید یا اقدام جدید بسازید.</div>}</section></div>
  </div>
}

type AttachmentDraft = { id: string; name: string; size: number; type: string }
type BaseDraft = { formName: string; organization: string; ownerUnit: string; purpose: string; audiences: string; briefProcess: string; priority: 'عادی' | 'فوری' | 'خیلی فوری'; attachments: AttachmentDraft[] }
type CommentDraft = { id: string; target: string; body: string; answer?: string; state: 'باز' | 'پاسخ‌داده‌شده'; time: string }
type HistoryDraft = { id: string; title: string; detail: string; time: string }
type RequestPayload = { base: BaseDraft; sections: FormSectionDraft[]; workflow: WorkflowDraft; comments: CommentDraft[]; history: HistoryDraft[] }
type ValidationIssue = { id: string; location: string; message: string; solution: string }

const initialBase: BaseDraft = { formName: 'فرم درخواست مرخصی', organization: 'شرکت سپهر', ownerUnit: 'منابع انسانی', purpose: 'ثبت و بررسی درخواست‌های مرخصی کارکنان', audiences: 'کارکنان و مدیران مستقیم', briefProcess: 'کارمند درخواست را ثبت می‌کند، مدیر بررسی می‌کند و منابع انسانی نتیجه را اعلام می‌کند.', priority: 'عادی', attachments: [] }
const initialComments: CommentDraft[] = [{ id: 'question-date', target: 'فیلد: تاریخ شروع', body: 'لطفاً مشخص کنید آیا تاریخ پایان می‌تواند پیش از تاریخ شروع باشد یا خیر.', state: 'باز', time: 'امروز، ۱۰:۳۵' }]
const initialHistory: HistoryDraft[] = [{ id: 'created', title: 'ایجاد پیش‌نویس', detail: 'درخواست طراحی فرم ایجاد شد.', time: '۱۴۰۵/۰۶/۱۶' }, { id: 'saved', title: 'ذخیره تغییرات', detail: 'طراحی فرم و گردش فرم به‌روزرسانی شدند.', time: 'امروز، ۱۰:۲۰' }]

function loadDraft<T>(key: string, fallback: T): T { const stored = localStorage.getItem(key); if (!stored) return fallback; try { return JSON.parse(stored) as T } catch { return fallback } }

function validationIssues(base: BaseDraft, sections: FormSectionDraft[], workflow: WorkflowDraft): ValidationIssue[] {
  const issues: ValidationIssue[] = []
  if (!base.formName.trim()) issues.push({ id: 'form-name', location: 'اطلاعات پایه ← نام فرم', message: 'نام فرم ثبت نشده است.', solution: 'یک نام روشن و قابل‌فهم برای فرم وارد کنید.' })
  if (!base.purpose.trim()) issues.push({ id: 'purpose', location: 'اطلاعات پایه ← هدف فرم', message: 'هدف فرم ثبت نشده است.', solution: 'توضیح دهید این فرم چه مسئله‌ای را حل می‌کند.' })
  const allFields = sections.flatMap((section) => section.fields.map((field) => ({ section, field })))
  const ids = allFields.map(({ field }) => field.technicalId.trim()).filter(Boolean)
  ids.filter((id, index) => ids.indexOf(id) !== index).filter((id, index, array) => array.indexOf(id) === index).forEach((id) => issues.push({ id: `duplicate-${id}`, location: 'طراحی فرم', message: `شناسه فنی «${id}» تکراری است.`, solution: 'برای هر فیلد یک شناسه فنی یکتا وارد کنید.' }))
  allFields.forEach(({ section, field }) => { if (!field.title.trim()) issues.push({ id: `title-${field.id}`, location: `طراحی فرم ← ${section.title}`, message: 'یک فیلد عنوان نمایشی ندارد.', solution: 'عنوانی که کاربر در فرم می‌بیند را وارد کنید.' }); if (!field.technicalId.trim()) issues.push({ id: `technical-${field.id}`, location: `طراحی فرم ← ${field.title || 'فیلد بدون عنوان'}`, message: 'شناسه فنی فیلد ثبت نشده است.', solution: 'یک شناسه انگلیسی و یکتا مانند start_date وارد کنید.' }); if ((field.type === 'SELECT' || field.type === 'RADIO') && !field.options.some((option) => option.active)) issues.push({ id: `options-${field.id}`, location: `طراحی فرم ← ${field.title || 'فیلد بدون عنوان'}`, message: 'فیلد انتخابی هیچ گزینه فعال ندارد.', solution: 'حداقل یک گزینه فعال با کد و عنوان اضافه کنید.' }) })
  if (!workflow.stages.length) issues.push({ id: 'stages', location: 'گردش فرم', message: 'هیچ مرحله‌ای تعریف نشده است.', solution: 'حداقل مرحله شروع گردش فرم را اضافه کنید.' })
  workflow.stages.forEach((stage) => { if (!stage.name.trim() || !stage.responsible.trim()) issues.push({ id: `stage-${stage.id}`, location: 'گردش فرم ← مراحل', message: `مرحله «${stage.name || 'بدون نام'}» مسئول ندارد.`, solution: 'یک نقش یا واحد مسئول برای مرحله مشخص کنید.' }) })
  workflow.actions.forEach((action) => { const hasTarget = Boolean(action.targetStageId); const hasTerminal = Boolean(action.terminalStatus); if (!action.title.trim()) issues.push({ id: `action-title-${action.id}`, location: 'گردش فرم ← اقدام‌ها', message: 'یک اقدام عنوان ندارد.', solution: 'عنوانی مانند تأیید، رد یا برگشت جهت اصلاح وارد کنید.' }); if (!action.sourceStageId) issues.push({ id: `action-source-${action.id}`, location: 'گردش فرم ← اقدام‌ها', message: 'مرحله مبدأ اقدام مشخص نشده است.', solution: 'یک مرحله مبدأ انتخاب کنید.' }); if (hasTarget === hasTerminal) issues.push({ id: `action-target-${action.id}`, location: `گردش فرم ← ${action.title || 'اقدام بدون عنوان'}`, message: 'اقدام باید فقط یک مرحله مقصد یا یک وضعیت پایانی داشته باشد.', solution: 'یکی از مقصد یا وضعیت پایانی را مشخص کنید و دیگری را خالی بگذارید.' }) })
  const terminalReachable = (() => { if (!workflow.stages[0]) return false; const visited = new Set<string>(); const queue = [workflow.stages[0].id]; while (queue.length) { const stage = queue.shift()!; if (visited.has(stage)) continue; visited.add(stage); for (const action of workflow.actions.filter((item) => item.sourceStageId === stage)) { if (action.terminalStatus) return true; if (action.targetStageId) queue.push(action.targetStageId) } } return false })()
  if (!terminalReachable) issues.push({ id: 'terminal-path', location: 'گردش فرم', message: 'حداقل یک مسیر پایان برای گردش فرم تعریف نشده است.', solution: 'از مرحله شروع، مسیری به یکی از وضعیت‌های پایانی ایجاد کنید.' })
  return issues
}

function downloadRequirementsExcel(base: BaseDraft, sections: FormSectionDraft[], workflow: WorkflowDraft, comments: CommentDraft[]) {
  const workbook = XLSX.utils.book_new()
  const guide = [['راهنما'], ['این فایل خروجی ساخت‌یافته نیازمندی طراحی فرم است.'], ['نام فرم', base.formName], ['سازمان', base.organization], ['تاریخ تولید', new Date().toLocaleDateString('fa-IR')]]
  const design = [['بخش', 'شناسه فنی', 'عنوان', 'نوع', 'اجباری', 'فقط‌خواندنی', 'راهنما', 'مقدار پیش‌فرض', 'مثال', 'شرط نمایش', 'محدودیت', 'منبع داده', 'منطق محاسبه'], ...sections.flatMap((section) => section.fields.map((field) => [section.title, field.technicalId, field.title, fieldTypeLabels[field.type], field.required ? 'بله' : 'خیر', field.readOnly ? 'بله' : 'خیر', field.help, field.defaultValue, field.exampleValue, field.visibilityRule, field.validationRule, field.dataSource, field.calculationLogic]))]
  const options = [['بخش', 'فیلد', 'شناسه فنی', 'کد گزینه', 'عنوان گزینه', 'ترتیب', 'فعال'], ...sections.flatMap((section) => section.fields.flatMap((field) => field.options.map((option, index) => [section.title, field.title, field.technicalId, option.code, option.title, index + 1, option.active ? 'بله' : 'خیر'])))]
  const flow = [['مرحله مبدأ', 'مسئول', 'عنوان اقدام', 'شرط', 'مرحله مقصد', 'وضعیت پایانی', 'اعلان‌گیرندگان', 'توضیحات'], ...workflow.actions.map((action) => { const source = workflow.stages.find((stage) => stage.id === action.sourceStageId); const target = workflow.stages.find((stage) => stage.id === action.targetStageId); return [source?.name || '', source?.responsible || '', action.title, action.condition, target?.name || '', action.terminalStatus ? terminalLabels[action.terminalStatus] : '', action.recipients, action.description] })]
  const questions = [['بخش', 'پرسش', 'وضعیت', 'پاسخ', 'زمان'], ...comments.map((comment) => [comment.target, comment.body, comment.state, comment.answer || '', comment.time])]
  ;[['راهنما', guide], ['طراحی فرم', design], ['گزینه‌ها', options], ['گردش کار', flow], ['سؤالات باز', questions]].forEach(([name, data]) => { const sheet = XLSX.utils.aoa_to_sheet(data as unknown[][]); sheet['!rtl'] = true; XLSX.utils.book_append_sheet(workbook, sheet, name as string) })
  XLSX.writeFile(workbook, 'formyar-requirements.xlsx')
}

function ReviewAndSubmit({ base, sections, workflow, comments, setComments, history, setHistory, submitted, onSubmit }: { base: BaseDraft; sections: FormSectionDraft[]; workflow: WorkflowDraft; comments: CommentDraft[]; setComments: (comments: CommentDraft[]) => void; history: HistoryDraft[]; setHistory: (history: HistoryDraft[]) => void; submitted: boolean; onSubmit: () => void }) {
  const issues = validationIssues(base, sections, workflow)
  const [commentText, setCommentText] = useState('')
  const [commentTarget, setCommentTarget] = useState('درخواست')
  const exportExcel = () => {
    const workbook = XLSX.utils.book_new()
    const guide = [['راهنما'], ['این فایل خروجی ساخت‌یافته نیازمندی طراحی فرم است.'], ['تاریخ تولید', new Date().toLocaleDateString('fa-IR')]]
    const design = [['بخش', 'شناسه فنی', 'عنوان', 'نوع', 'اجباری', 'فقط‌خواندنی', 'راهنما', 'مقدار پیش‌فرض', 'مثال', 'شرط نمایش', 'محدودیت', 'منبع داده', 'منطق محاسبه'], ...sections.flatMap((section) => section.fields.map((field) => [section.title, field.technicalId, field.title, fieldTypeLabels[field.type], field.required ? 'بله' : 'خیر', field.readOnly ? 'بله' : 'خیر', field.help, field.defaultValue, field.exampleValue, field.visibilityRule, field.validationRule, field.dataSource, field.calculationLogic]))]
    const options = [['بخش', 'فیلد', 'شناسه فنی', 'کد گزینه', 'عنوان گزینه', 'ترتیب', 'فعال'], ...sections.flatMap((section) => section.fields.flatMap((field) => field.options.map((option, index) => [section.title, field.title, field.technicalId, option.code, option.title, index + 1, option.active ? 'بله' : 'خیر'])))]
    const flow = [['مرحله مبدأ', 'مسئول', 'عنوان اقدام', 'شرط', 'مرحله مقصد', 'وضعیت پایانی', 'اعلان‌گیرندگان', 'توضیحات'], ...workflow.actions.map((action) => { const source = workflow.stages.find((stage) => stage.id === action.sourceStageId); const target = workflow.stages.find((stage) => stage.id === action.targetStageId); return [source?.name || '', source?.responsible || '', action.title, action.condition, target?.name || '', action.terminalStatus ? terminalLabels[action.terminalStatus] : '', action.recipients, action.description] })]
    const questions = [['بخش', 'پرسش', 'وضعیت', 'پاسخ', 'زمان'], ...comments.map((comment) => [comment.target, comment.body, comment.state, comment.answer || '', comment.time])]
    ;[['راهنما', guide], ['طراحی فرم', design], ['گزینه‌ها', options], ['گردش کار', flow], ['سؤالات باز', questions]].forEach(([name, data]) => { const sheet = XLSX.utils.aoa_to_sheet(data as unknown[][]); sheet['!rtl'] = true; XLSX.utils.book_append_sheet(workbook, sheet, name as string) })
    XLSX.writeFile(workbook, 'formyar-requirements.xlsx')
  }
  const addComment = () => { if (!commentText.trim()) return; const comment = { id: crypto.randomUUID(), target: commentTarget, body: commentText, state: 'باز' as const, time: 'همین حالا' }; setComments([comment, ...comments]); setHistory([{ id: crypto.randomUUID(), title: 'ثبت پرسش', detail: `پرسش جدید برای «${commentTarget}» ثبت شد.`, time: 'همین حالا' }, ...history]); setCommentText('') }
  return <div id="review-print" className="review-screen"><div className={`review-status ${submitted ? 'submitted' : issues.length ? 'blocked' : 'ready'}`}><span>{submitted ? '✓' : issues.length ? '!' : '✓'}</span><div><strong>{submitted ? 'برای بررسی ارسال شد' : issues.length ? `${issues.length} مورد نیازمند تکمیل است` : 'آماده ارسال برای بررسی'}</strong><p>{submitted ? 'کارشناس شرکت می‌تواند درخواست را بررسی کند.' : issues.length ? 'موارد زیر را اصلاح کنید تا ارسال فعال شود.' : 'همه کنترل‌های لازم با موفقیت انجام شده‌اند.'}</p></div>{!submitted && <button className="primary" disabled={issues.length > 0} onClick={onSubmit}>ارسال برای بررسی <Icon name="arrow" /></button>}</div>
    {issues.length > 0 && <section className="review-card issue-list"><h3>موارد نیازمند تکمیل</h3>{issues.map((issue) => <div key={issue.id}><span>!</span><p><strong>{issue.message}</strong><small>محل: {issue.location} — راه‌حل: {issue.solution}</small></p></div>)}</section>}
    <div className="review-two-col"><section className="review-card"><div className="review-card-title"><div><h3>پیش‌نمایش فرم</h3><p>{base.formName || 'فرم بدون نام'}</p></div><span>{sections.reduce((count, section) => count + section.fields.length, 0)} فیلد</span></div>{sections.map((section) => <div className="form-preview-section" key={section.id}><h4>{section.title}</h4>{section.fields.map((field) => <div className="preview-field" key={field.id}><label>{field.title || 'فیلد بدون عنوان'} {field.required && <em>*</em>}</label><div>{field.type === 'SELECT' || field.type === 'RADIO' ? <span className="preview-select">{field.options.filter((option) => option.active).map((option) => option.title).join('، ') || 'گزینه‌ای تعریف نشده'}</span> : field.type === 'BOOLEAN' ? <span className="preview-check">☐ بله / خیر</span> : <span className="preview-input">{field.exampleValue || field.help || fieldTypeLabels[field.type]}</span>}</div></div>)}</div>)}</section>
      <section className="review-card"><div className="review-card-title"><div><h3>خلاصه گردش فرم</h3><p>{workflow.stages.length} مرحله · {workflow.actions.length} اقدام</p></div></div><div className="review-flow">{workflow.actions.map((action) => <div key={action.id}><strong>{workflow.stages.find((stage) => stage.id === action.sourceStageId)?.name || '—'}</strong><span>{action.title || 'اقدام'}</span><i>←</i><b>{action.terminalStatus ? terminalLabels[action.terminalStatus] : workflow.stages.find((stage) => stage.id === action.targetStageId)?.name || '—'}</b></div>)}</div></section></div>
    <div className="review-two-col"><section className="review-card"><div className="review-card-title"><div><h3>پرسش‌ها و اصلاحات</h3><p>پرسش‌ها به بخش مشخص متصل می‌شوند.</p></div></div><div className="comment-compose"><select value={commentTarget} onChange={(event) => setCommentTarget(event.target.value)}><option>درخواست</option>{sections.flatMap((section) => section.fields.map((field) => <option key={field.id}>{`فیلد: ${field.title || 'بدون عنوان'}`}</option>))}{workflow.stages.map((stage) => <option key={stage.id}>{`مرحله: ${stage.name || 'بدون نام'}`}</option>)}</select><textarea value={commentText} onChange={(event) => setCommentText(event.target.value)} placeholder="پرسش یا توضیح خود را ثبت کنید" rows={2} /><button className="secondary" onClick={addComment}>ثبت پرسش</button></div><div className="comment-list">{comments.map((comment) => <div key={comment.id}><span className={comment.state === 'باز' ? 'open-dot' : 'resolved-dot'} /><p><small>{comment.target} · {comment.time}</small><strong>{comment.body}</strong><em>{comment.state}</em></p></div>)}</div></section>
      <section className="review-card"><div className="review-card-title"><div><h3>خروجی‌ها</h3><p>برای اشتراک‌گذاری یا تأیید نهایی.</p></div></div><div className="export-actions"><button className="export-button" onClick={exportExcel}><span>▦</span><div><strong>Excel ساخت‌یافته</strong><small>راهنما، طراحی فرم، گزینه‌ها، گردش کار و سؤالات باز</small></div><i>↓</i></button><button className="export-button" onClick={() => window.print()}><span>▤</span><div><strong>چاپ / ذخیره PDF</strong><small>خلاصه فارسی نیازمندی برای تأیید مشتری</small></div><i>↓</i></button></div></section></div>
    <section className="review-card history-card"><div className="review-card-title"><div><h3>تاریخچه تغییرات</h3><p>رویدادهای ثبت‌شده در این درخواست</p></div></div><div className="review-history">{history.map((event) => <div key={event.id}><b /><p><strong>{event.title}</strong><span>{event.detail}</span></p><small>{event.time}</small></div>)}</div></section>
  </div>
}

function FutureStep({ index }: { index: number }) { const copy = ['بازبینی و ارسال', 'در مرحله ۷، اعتبارسنجی، پرسش‌ها و خروجی‌ها به این بخش افزوده می‌شوند.']; return <div className="future-panel"><div className="future-icon">✓</div><h3>{copy[0]}</h3><p>{copy[1]}</p></div> }

function RequestDetail({ onBack, onNew, role, request, payload, onPayloadChange, onStatusChange }: { onBack: () => void; onNew: () => void; role: Role; request: RequestListItem; payload: RequestPayload; onPayloadChange: (updater: (payload: RequestPayload) => RequestPayload) => void; onStatusChange: (status: string) => void }) {
  const [tab, setTab] = useState<'overview' | 'form' | 'workflow' | 'questions' | 'history'>('overview')
  const tabs = [['overview', 'نمای کلی'], ['form', 'طراحی فرم'], ['workflow', 'گردش فرم'], ['questions', 'پرسش‌ها'], ['history', 'تاریخچه']] as const
  const needsCompletion = request.status === 'نیازمند تکمیل مشتری'
  const openComments = payload.comments.filter((item) => item.state === 'باز')
  const returnForCorrection = (comment: CommentDraft) => {
    onPayloadChange((current) => ({ ...current, comments: [comment, ...current.comments], history: [{ id: crypto.randomUUID(), title: 'بازگشت برای اصلاح', detail: `کارشناس برای «${comment.target}» توضیح اصلاحی ثبت کرد.`, time: 'همین حالا' }, ...current.history] }))
    onStatusChange('نیازمند تکمیل مشتری')
  }
  const answerComment = (commentId: string, answer: string) => {
    onPayloadChange((current) => ({ ...current, comments: current.comments.map((item) => item.id === commentId ? { ...item, answer, state: 'پاسخ‌داده‌شده', time: 'همین حالا' } : item), history: [{ id: crypto.randomUUID(), title: 'پاسخ مشتری به اصلاح', detail: 'مشتری پاسخ و اصلاح موردنیاز را ثبت کرد.', time: 'همین حالا' }, ...current.history] }))
    onStatusChange('ارسال‌شده توسط مشتری')
  }
  return <><div className="page-heading"><div><button className="back-link" onClick={onBack}><Icon name="arrow" />بازگشت به درخواست‌ها</button><div className="title-line"><h1>{request.name}</h1><span className={`badge ${request.tone}`}>{request.status}</span></div><p>{request.organization} · آخرین تغییر: {request.date}</p></div>{role === 'کارشناس' ? <span className="specialist-label">بررسی توسط کارشناس</span> : role === 'مدیر' && request.status === 'آماده طراحی' ? <button className="primary" onClick={() => onStatusChange('بسته‌شده')}>بستن درخواست</button> : <button className="primary" onClick={onNew}><Icon name="plus" />درخواست جدید</button>}</div>{role === 'کارشناس' && <SpecialistReviewPanel status={request.status} payload={payload} onReturnForCorrection={returnForCorrection} onStatusChange={onStatusChange} />}<div className="detail-tabs">{tabs.map(([id, label]) => <button key={id} className={tab === id ? 'active' : ''} onClick={() => setTab(id)}>{label}{id === 'questions' && openComments.length > 0 && <span>{openComments.length}</span>}</button>)}</div>{tab === 'overview' && <div className="detail-grid"><section>{needsCompletion && <div className="alert"><span>!</span><div><strong>{openComments.length} مورد نیاز به تکمیل دارد</strong><p>{openComments[0]?.body || 'کارشناس درخواست اصلاح ثبت کرده است.'}</p></div><button onClick={() => setTab('questions')}>مشاهده و پاسخ</button></div>}<div className="card info-card"><h2>اطلاعات پایه</h2><div className="info-list"><div><span>هدف فرم</span><p>{payload.base.purpose}</p></div><div><span>مخاطبان</span><p>{payload.base.audiences}</p></div><div><span>اولویت</span><p>{payload.base.priority}</p></div><div><span>واحد مالک</span><p>{payload.base.ownerUnit}</p></div></div></div></section><aside className="card activity"><h2>فعالیت‌های اخیر</h2><ActivityTimeline /></aside></div>}{tab === 'form' && <DetailDesignPanel sections={payload.sections} />}{tab === 'workflow' && <DetailWorkflowPanel workflow={payload.workflow} />}{tab === 'questions' && <DetailQuestionsPanel role={role} status={request.status} comments={payload.comments} onAnswered={answerComment} />}{tab === 'history' && <section className="card activity detail-full"><h2>تاریخچه تغییرات</h2><ActivityTimeline /></section>}</>
}

function ActivityTimeline() { return <div className="timeline"><div><b className="orange-dot" /><p><strong>نیاز به تکمیل</strong><small>کارشناس پرسشی ثبت کرد · امروز، ۱۰:۳۵</small></p></div><div><b className="blue-dot" /><p><strong>ارسال برای بررسی</strong><small>توسط مریم احمدی · دیروز، ۱۵:۱۰</small></p></div><div><b className="gray-dot" /><p><strong>ایجاد پیش‌نویس</strong><small>توسط مریم احمدی · ۱۴۰۵/۰۶/۱۸</small></p></div></div> }
function DetailDesignPanel({ sections }: { sections: FormSectionDraft[] }) { return <section className="detail-panel"><h2>طراحی فرم</h2>{sections.map((section) => <div className="detail-section" key={section.id}><h3>{section.title}</h3>{section.fields.map((field) => <div key={field.id}><strong>{field.title}</strong><span>{fieldTypeLabels[field.type]} · {field.required ? 'اجباری' : 'اختیاری'}</span><small>شناسه: {field.technicalId}</small></div>)}</div>)}</section> }
function DetailWorkflowPanel({ workflow }: { workflow: WorkflowDraft }) { return <section className="detail-panel"><h2>گردش فرم</h2><div className="detail-flow">{workflow.actions.map((action) => <div key={action.id}><strong>{workflow.stages.find((stage) => stage.id === action.sourceStageId)?.name}</strong><span>{action.title}</span><i>←</i><b>{action.terminalStatus ? terminalLabels[action.terminalStatus] : workflow.stages.find((stage) => stage.id === action.targetStageId)?.name}</b></div>)}</div></section> }
function DetailQuestionsPanel({ role, status, comments, onAnswered }: { role: Role; status: string; comments: CommentDraft[]; onAnswered: (commentId: string, answer: string) => void }) { const [answers, setAnswers] = useState<Record<string, string>>({}); const canAnswer = role === 'مشتری' && status === 'نیازمند تکمیل مشتری'; return <section className="detail-panel"><h2>پرسش‌ها و اصلاحات</h2>{comments.length === 0 ? <p className="empty-actions">پرسش یا اصلاح بازی ثبت نشده است.</p> : comments.map((comment) => <div className="question-thread" key={comment.id}><div className="question-detail"><span>!</span><div><strong>{comment.body}</strong><small>{comment.target} · ثبت‌شده توسط کارشناس · {comment.time}</small></div><em>{comment.state}</em></div>{comment.answer && <div className="answer-record"><strong>پاسخ مشتری:</strong><p>{comment.answer}</p></div>}{canAnswer && comment.state === 'باز' && <div className="answer-box"><textarea value={answers[comment.id] ?? ''} onChange={(event) => setAnswers({ ...answers, [comment.id]: event.target.value })} placeholder="پاسخ یا توضیح اصلاحی خود را بنویسید" rows={3} /><button className="primary" disabled={!(answers[comment.id] ?? '').trim()} onClick={() => onAnswered(comment.id, answers[comment.id])}>ثبت پاسخ و ارسال برای بررسی</button></div>}</div>)}</section> }

function SpecialistReviewPanel({ status, payload, onReturnForCorrection, onStatusChange }: { status: string; payload: RequestPayload; onReturnForCorrection: (comment: CommentDraft) => void; onStatusChange: (status: string) => void }) {
  const [question, setQuestion] = useState('')
  const [questionTarget, setQuestionTarget] = useState('درخواست')
  const [showSummary, setShowSummary] = useState(false)
  const targets = ['درخواست', ...payload.sections.flatMap((section) => section.fields.map((field) => `فیلد: ${field.title || field.technicalId || 'بدون عنوان'}`)), ...payload.workflow.stages.map((stage) => `مرحله: ${stage.name || 'بدون نام'}`), ...payload.workflow.actions.map((action) => `اقدام: ${action.title || 'بدون عنوان'}`)]
  const submitQuestion = () => { if (!question.trim()) return; onReturnForCorrection({ id: crypto.randomUUID(), target: questionTarget, body: question.trim(), state: 'باز', time: 'همین حالا' }); setQuestion('') }
  return <section className="specialist-review"><div className="review-decision"><div><span>وضعیت بررسی</span><strong>{status}</strong><small>{status === 'نیازمند تکمیل مشتری' ? 'مشتری باید به توضیح اصلاحی پاسخ دهد یا بخش مشخص‌شده را اصلاح کند.' : 'اقدام بعدی را برای این درخواست تعیین کنید.'}</small></div><div className="decision-actions">{status === 'ارسال‌شده توسط مشتری' && <button className="secondary" onClick={() => onStatusChange('در حال بررسی')}>شروع بررسی</button>}{status === 'در حال بررسی' && <button className="primary" onClick={() => onStatusChange('تأیید نهایی')}>تأیید نهایی</button>}{status === 'تأیید نهایی' && <button className="primary" onClick={() => onStatusChange('آماده طراحی')}>ارسال برای طراحی</button>}{status === 'آماده طراحی' && <button className="secondary" onClick={() => onStatusChange('بسته‌شده')}>بستن درخواست</button>}</div></div><div className="review-workbench"><section><h3>بازگرداندن برای اصلاح مشتری</h3><div className="specialist-question-form"><select value={questionTarget} onChange={(event) => setQuestionTarget(event.target.value)}>{targets.map((target) => <option key={target}>{target}</option>)}</select><textarea value={question} onChange={(event) => setQuestion(event.target.value)} rows={3} placeholder="توضیح دهید مشتری دقیقاً چه چیزی را اصلاح یا روشن کند" /><button className="secondary" disabled={status !== 'در حال بررسی' || !question.trim()} onClick={submitQuestion}>بازگرداندن برای اصلاح</button></div><div className="specialist-questions">{payload.comments.map((item) => <div key={item.id}><b>!</b><p><small>{item.target} · {item.time}</small><strong>{item.body}</strong>{item.answer && <small>پاسخ مشتری: {item.answer}</small>}</p><span>{item.state}</span></div>)}</div></section><aside><h3>خروجی قابل تحویل</h3><p>ساختار فرم، گزینه‌ها، گردش کار و پرسش‌ها برای تیم طراحی آماده مشاهده است.</p><button className="text-button" onClick={() => setShowSummary(!showSummary)}>{showSummary ? 'بستن خلاصه نیازمندی' : 'مشاهده خلاصه نیازمندی'} <Icon name="arrow" /></button><button className="text-button" onClick={() => downloadRequirementsExcel(payload.base, payload.sections, payload.workflow, payload.comments)}>دریافت Excel ساخت‌یافته <Icon name="arrow" /></button></aside></div>{showSummary && <div className="specialist-output-summary"><div><span>نام فرم</span><strong>{payload.base.formName}</strong></div><div><span>هدف فرم</span><strong>{payload.base.purpose}</strong></div><div><span>فیلدها</span><strong>{payload.sections.flatMap((section) => section.fields).map((field) => field.title).join('، ')}</strong></div><div><span>مسیرهای گردش</span><strong>{payload.workflow.actions.map((action) => action.title).join('، ')}</strong></div></div>}</section>
}

function Dashboard({ onRequests, rows }: { onRequests: () => void; rows: RequestListItem[] }) { const count = (status: string) => rows.filter((item) => item.status === status).length; return <><div className="page-heading"><div><h1>داشبورد مدیریت</h1><p>نمای کلی از وضعیت درخواست‌های طراحی فرم</p></div><button className="secondary" onClick={onRequests}>مشاهده همه درخواست‌ها</button></div><section className="stats-grid manager"><Stat icon="file" value={String(rows.length)} label="کل درخواست‌ها" color="blue" /><Stat icon="clock" value={String(count('در حال بررسی'))} label="در حال بررسی" color="orange" /><Stat icon="chat" value={String(count('نیازمند تکمیل مشتری'))} label="نیازمند تکمیل" color="purple" /><Stat icon="check" value={String(count('آماده طراحی'))} label="آماده طراحی" color="green" /></section><section className="dashboard-grid"><div className="card chart-card"><div className="section-title"><div><h2>وضعیت درخواست‌ها</h2><p>تفکیک درخواست‌های ثبت‌شده در این نسخه</p></div></div><div className="bar-chart">{[['پیش‌نویس', count('پیش‌نویس'), 'blue'], ['بررسی', count('در حال بررسی'), 'orange'], ['تکمیل', count('نیازمند تکمیل مشتری'), 'purple'], ['آماده طراحی', count('آماده طراحی'), 'green']].map(([label, value, color]) => <div key={label as string}><i className={color as string} style={{ height: `${Math.max(Number(value) * 24, 8)}px` }} /><span>{label} ({value})</span></div>)}</div></div><div className="card"><h2>نیازمند توجه</h2><div className="attention"><span className="count">{count('نیازمند تکمیل مشتری')}</span><p>درخواست‌های در انتظار پاسخ مشتری را از فهرست پیگیری کنید.</p><button className="text-button" onClick={onRequests}>مشاهده درخواست‌ها <Icon name="arrow" /></button></div></div></section></> }

type AdminUser = { id: string; name: string; role: Role; organization: string; active: boolean }
type FormTemplate = { id: string; title: string; description: string; category: string; active: boolean }
const initialAdminUsers: AdminUser[] = [{ id: 'u1', name: 'مریم احمدی', role: 'مشتری', organization: 'شرکت سپهر', active: true }, { id: 'u2', name: 'علی رضایی', role: 'کارشناس', organization: 'شرکت برید', active: true }, { id: 'u3', name: 'سارا محمدی', role: 'مدیر', organization: 'شرکت برید', active: true }]
const initialTemplates: FormTemplate[] = [{ id: 't1', title: 'درخواست مرخصی', description: 'ساختار اولیه فرم و گردش مرخصی کارکنان', category: 'منابع انسانی', active: true }, { id: 't2', title: 'درخواست خرید', description: 'الگوی درخواست و تأیید خرید سازمانی', category: 'مالی و پشتیبانی', active: true }]

function UserManagement({ users, setUsers, toast }: { users: AdminUser[]; setUsers: (users: AdminUser[]) => void; toast: (message: string) => void }) {
  const [draft, setDraft] = useState({ name: '', role: 'مشتری' as Role, organization: '' })
  const addUser = () => { if (!draft.name.trim() || !draft.organization.trim()) return toast('نام و سازمان کاربر را وارد کنید.'); setUsers([{ id: crypto.randomUUID(), ...draft, active: true }, ...users]); setDraft({ name: '', role: 'مشتری', organization: '' }); toast('کاربر جدید اضافه شد.') }
  return <><div className="page-heading"><div><h1>مدیریت کاربران</h1><p>کاربران نمایشی و نقش دسترسی آن‌ها را در MVP مدیریت کنید.</p></div></div><section className="management-grid"><div className="card management-form"><h2>افزودن کاربر</h2><input value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} placeholder="نام و نام خانوادگی" /><select value={draft.role} onChange={(event) => setDraft({ ...draft, role: event.target.value as Role })}><option>مشتری</option><option>کارشناس</option><option>مدیر</option></select><input value={draft.organization} onChange={(event) => setDraft({ ...draft, organization: event.target.value })} placeholder="سازمان" /><button className="primary" onClick={addUser}><Icon name="plus" />افزودن کاربر</button></div><div className="card management-list"><h2>کاربران فعال</h2>{users.map((user) => <div key={user.id}><div><strong>{user.name}</strong><small>{user.role} · {user.organization}</small></div><button className={user.active ? 'status-toggle active' : 'status-toggle'} onClick={() => setUsers(users.map((item) => item.id === user.id ? { ...item, active: !item.active } : item))}>{user.active ? 'فعال' : 'غیرفعال'}</button><button className="delete" onClick={() => setUsers(users.filter((item) => item.id !== user.id))}>×</button></div>)}</div></section></>
}

function TemplateManagement({ templates, setTemplates, toast }: { templates: FormTemplate[]; setTemplates: (templates: FormTemplate[]) => void; toast: (message: string) => void }) {
  const [draft, setDraft] = useState({ title: '', description: '', category: '' })
  const addTemplate = () => { if (!draft.title.trim() || !draft.category.trim()) return toast('نام قالب و دسته‌بندی را وارد کنید.'); setTemplates([{ id: crypto.randomUUID(), ...draft, active: true }, ...templates]); setDraft({ title: '', description: '', category: '' }); toast('قالب جدید اضافه شد.') }
  return <><div className="page-heading"><div><h1>قالب‌های فرم</h1><p>برای شروع سریع درخواست‌های مشابه، قالب‌های اولیه بسازید و مدیریت کنید.</p></div></div><section className="management-grid"><div className="card management-form"><h2>قالب جدید</h2><input value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} placeholder="نام قالب" /><input value={draft.category} onChange={(event) => setDraft({ ...draft, category: event.target.value })} placeholder="دسته‌بندی" /><textarea value={draft.description} onChange={(event) => setDraft({ ...draft, description: event.target.value })} rows={3} placeholder="توضیح کوتاه قالب" /><button className="primary" onClick={addTemplate}><Icon name="plus" />افزودن قالب</button></div><div className="card management-list"><h2>قالب‌های موجود</h2>{templates.map((template) => <div key={template.id}><div><strong>{template.title}</strong><small>{template.category} · {template.description || 'بدون توضیح'}</small></div><button className={template.active ? 'status-toggle active' : 'status-toggle'} onClick={() => setTemplates(templates.map((item) => item.id === template.id ? { ...item, active: !item.active } : item))}>{template.active ? 'فعال' : 'غیرفعال'}</button><button className="delete" onClick={() => setTemplates(templates.filter((item) => item.id !== template.id))}>×</button></div>)}</div></section></>
}

function HelpCenter({ role, onNavigate }: { role: Role; onNavigate: (page: Page) => void }) {
  const [activeRole, setActiveRole] = useState<Role>(role)
  const content: Record<Role, { title: string; intro: string; steps: Array<[string, string]> }> = {
    مشتری: { title: 'راهنمای کامل مشتری', intro: 'اگر اولین‌بار است از فرم‌یار استفاده می‌کنید، همین پنج گام را به ترتیب انجام دهید. هر جا علامت سؤال دیدید، توضیح همان بخش را باز کنید.', steps: [['۱. شروع و ذخیره پیش‌نویس', 'از «درخواست جدید» شروع کنید. لازم نیست همه اطلاعات را یکجا وارد کنید؛ دکمه «ذخیره پیش‌نویس» اطلاعات فعلی را در همین مرورگر نگه می‌دارد.'], ['۲. اطلاعات پایه', 'نام فرم را طوری بنویسید که همه همکاران بفهمند؛ مانند «درخواست خرید». هدف فرم باید بگوید فرم چه مسئله‌ای را حل می‌کند. سازمان، واحد مالک، مخاطبان، شرح فرایند و اولویت را نیز تکمیل کنید. فایل Word، Excel، PDF یا تصویر نمونه را با دکمه پیوست انتخاب کنید.'], ['۳. طراحی فرم', 'ابتدا بخش‌هایی مانند «اطلاعات درخواست» و «تأییدها» بسازید. سپس در هر بخش فیلد اضافه کنید. برای هر فیلد عنوان، شناسه فنی انگلیسی و یکتا، نوع فیلد و اجباری یا اختیاری بودن را مشخص کنید. در کشویی و رادیویی، گزینه‌ها را با کد و عنوان وارد کرده و دست‌کم یک گزینه را فعال نگه دارید.'], ['۴. گردش فرم', 'هر مرحله نشان می‌دهد کار دست چه نقش یا واحدی است؛ مانند «بررسی مدیر». هر اقدام را جداگانه ثبت کنید؛ مانند «تأیید»، «رد» یا «برگشت جهت اصلاح». برای هر اقدام فقط یک مقصد انتخاب کنید: مرحله بعد یا وضعیت پایانی. حداقل یک مسیر باید به پایان برسد.'], ['۵. بازبینی، ارسال و اصلاح', 'در بازبینی، خطاها همراه محل و راه‌حل نمایش داده می‌شوند. پس از رفع آن‌ها، «ارسال برای بررسی» را بزنید. اگر کارشناس درخواست را برگرداند، وارد همان درخواست شوید، تب «پرسش‌ها» را باز کنید، پاسخ یا توضیح اصلاحی را بنویسید و دوباره ارسال کنید.']] },
    کارشناس: { title: 'راهنمای کامل کارشناس', intro: 'کارشناس درخواست را بررسی می‌کند، ابهام‌ها را دقیقاً به بخش مرتبط متصل می‌کند و درخواست کامل را برای طراحی آماده می‌سازد.', steps: [['۱. انتخاب درخواست و شروع بررسی', 'از «درخواست‌های قابل بررسی» یک مورد را باز کنید. ابتدا وضعیت، اطلاعات پایه، طراحی فرم و گردش فرم را بخوانید. سپس «شروع بررسی» را بزنید تا وضعیت به «در حال بررسی» تغییر کند.'], ['۲. کنترل کیفیت طراحی فرم', 'بررسی کنید نام و هدف روشن باشد، برای هر فیلد عنوان و شناسه فنی وجود داشته باشد، شناسه‌ها تکراری نباشند و فیلدهای کشویی/رادیویی گزینه فعال داشته باشند. ابهام‌های قواعد نمایش، اعتبارسنجی، منبع داده یا محاسبه را ثبت کنید.'], ['۳. بازگرداندن برای اصلاح', 'در بخش «بازگرداندن برای اصلاح مشتری»، مقصد را از میان درخواست، فیلد، مرحله یا اقدام انتخاب کنید. سپس دقیق و عملی بنویسید مشتری چه چیزی را اصلاح کند؛ مثال: «برای فیلد مبلغ، سقف مجاز و واحد پول را مشخص کنید.» دکمه «بازگرداندن برای اصلاح» وضعیت را به «نیازمند تکمیل مشتری» تغییر می‌دهد.'], ['۴. بررسی پاسخ مشتری و تصمیم', 'پس از ارسال مجدد مشتری، تب «پرسش‌ها» را ببینید. پاسخ ثبت‌شده زیر همان توضیح نمایش داده می‌شود. اگر همه موارد کامل است «تأیید نهایی» و سپس «ارسال برای طراحی» را بزنید. در غیر این صورت، یک توضیح جدید و مشخص ثبت کنید.'], ['۵. تحویل خروجی', 'از «مشاهده خلاصه نیازمندی» برای کنترل نهایی استفاده کنید. «دریافت Excel ساخت‌یافته» فایل موردنیاز تیم طراحی شامل راهنما، طراحی فرم، گزینه‌ها، گردش کار و پرسش‌ها را تولید می‌کند.']] },
    مدیر: { title: 'راهنمای کامل مدیر', intro: 'مدیر، جریان کلی درخواست‌ها، کاربران نمایشی و قالب‌های پرتکرار را کنترل می‌کند.', steps: [['۱. داشبورد', 'تعداد کل درخواست‌ها و موارد در حال بررسی، نیازمند تکمیل و آماده طراحی را ببینید. برای پیگیری هر مورد، «مشاهده همه درخواست‌ها» را انتخاب کنید.'], ['۲. فهرست درخواست‌ها', 'با جست‌وجو، وضعیت و سازمان، درخواست موردنظر را پیدا کنید. جزئیات درخواست، مسیر گردش و پرسش‌های باز را بررسی کنید. درخواست «آماده طراحی» را در صورت پایان کار با دکمه «بستن درخواست» مختومه کنید.'], ['۳. مدیریت کاربران', 'در بخش کاربران، نام، نقش و سازمان را وارد و کاربر را اضافه کنید. دکمه «فعال/غیرفعال» فقط دسترسی نمایشی آن کاربر را در همین نسخه کنترل می‌کند.'], ['۴. مدیریت قالب‌ها', 'برای موضوعات پرتکرار مانند مرخصی یا خرید، قالبی با نام، دسته‌بندی و توضیح بسازید. قالب‌های غیرفعال را نگه دارید تا در پیشنهادهای بعدی استفاده نشوند.']] },
  }
  const guide = content[activeRole]
  return <><div className="page-heading"><div><h1>راهنمای استفاده از فرم‌یار <ContextHelp title="راهنمای نقش‌ها" text="نقش خود را انتخاب کنید تا مراحل دقیق همان نقش را ببینید. این راهنما برای کاربران بدون تجربه قبلی نوشته شده است." /></h1><p>راهنمای عملی و مرحله‌به‌مرحله برای استفاده کامل از سامانه.</p></div><button className="secondary" onClick={() => onNavigate(activeRole === 'مدیر' ? 'dashboard' : 'home')}>بازگشت به میزکار</button></div><section className="help-roles">{(['مشتری', 'کارشناس', 'مدیر'] as Role[]).map((item) => <button key={item} className={activeRole === item ? 'active' : ''} onClick={() => setActiveRole(item)}>{item}</button>)}</section><section className="help-card"><span className="help-big-icon">?</span><div><h2>{guide.title}</h2><p>{guide.intro}</p></div>{guide.steps.map(([title, text]) => <article key={title}><h3>{title}</h3><p>{text}</p></article>)}</section><section className="help-tips"><h2>نکته‌های مهم برای همه کاربران</h2><ul><li>اطلاعات این نسخه در مرورگر فعلی ذخیره می‌شود؛ با پاک‌کردن داده‌های مرورگر ممکن است پیش‌نویس‌ها از بین بروند.</li><li>هر اقدام گردش را جدا ثبت کنید؛ چند تصمیم را در یک اقدام ننویسید.</li><li>برای هر فیلد، عنوان قابل‌فهم و شناسه فنی یکتا وارد کنید.</li><li>پس از ارسال، از فهرست درخواست‌ها وضعیت را پیگیری کنید.</li><li>علامت سؤال کنار عنوان بخش‌ها، راهنمای کوتاه همان صفحه را نمایش می‌دهد.</li></ul></section></>
}

function Placeholder({ title, text, icon }: { title: string; text: string; icon: string }) { return <section className="placeholder"><div><Icon name={icon} /></div><h1>{title}</h1><p>{text}</p></section> }
